insert into public.lessons (slug, course_order, unit_order, unit_title, title, scene_title, summary, duration_minutes, status, published_at, grammar, dialogue, story_title, story_english, story_chinese, content_version)
values ('survival-05', 5, 1, '敢开口', '听不懂也能继续', '第一次见面复习', '第 5 个课程日：第一次见面复习', 6, 'published', timezone('utc', now()), '{"title":"礼貌请求","pattern":"Could you + 动词?","explanation":"Could you 比直接命令更礼貌，后面使用动词原形。","exampleEnglish":"Could you repeat that?","exampleChinese":"你可以重复一遍吗？"}'::jsonb, '[{"speaker":"A","english":"The meeting starts at eight thirty.","chinese":"会议八点半开始。"},{"speaker":"B","english":"Sorry, I don''t understand.","chinese":"抱歉，我没听懂。"},{"speaker":"B","english":"Could you say that again slowly?","chinese":"你可以慢慢再说一遍吗？"},{"speaker":"A","english":"Of course. Eight thirty.","chinese":"当然，八点半。"}]'::jsonb, '没听懂不是结束', 'A new friend speaks too fast. Lin does not pretend to understand. She says sorry and asks the friend to repeat the time slowly. This simple request gives her another chance. Good communication is not perfect English; it is finding a way to continue.', '新朋友说得太快，小林没有假装听懂。她先道歉，再请对方慢慢重复时间。这个简单请求给了她第二次机会。好的沟通不是完美英语，而是想办法继续。', 1)
