insert into public.lessons (slug, course_order, unit_order, unit_title, title, scene_title, summary, duration_minutes, status, published_at, grammar, dialogue, story_title, story_english, story_chinese, content_version)
values ('survival-09', 9, 2, '吃饭点单', '口味与忌口', '告诉店员饮食需求', '第 9 个课程日：告诉店员饮食需求', 6, 'published', timezone('utc', now()), '{"title":"说明身体情况","pattern":"I''m allergic to + 食物","explanation":"allergic 后面用 to，再接会引发过敏的食物。","exampleEnglish":"I''m allergic to milk.","exampleChinese":"我对牛奶过敏。"}'::jsonb, '[{"speaker":"Staff","english":"Do you like spicy food?","chinese":"你喜欢辣的食物吗？"},{"speaker":"Lin","english":"A little. Not too spicy, please.","chinese":"一点点，请不要太辣。"},{"speaker":"Lin","english":"And I''m allergic to peanuts.","chinese":"另外我对花生过敏。"},{"speaker":"Staff","english":"No problem. I''ll tell the kitchen.","chinese":"没问题，我会告诉厨房。"}]'::jsonb, '重要的话先说', 'Lin likes trying local food, but she has a peanut allergy. Before she orders, she tells the staff clearly. The staff checks the dish with the kitchen. Lin can enjoy her meal because she speaks up about what her body needs.', '小林喜欢尝试当地食物，但她对花生过敏。点餐前，她清楚地告诉店员。店员向厨房确认了菜品。因为主动说出身体需求，小林可以安心享用这顿饭。', 1)
