insert into public.lessons (slug, course_order, unit_order, unit_title, title, scene_title, summary, duration_minutes, status, published_at, grammar, dialogue, story_title, story_english, story_chinese, content_version)
values ('survival-22', 22, 5, '购物求助', '尺码颜色与试穿', '服装店', '第 22 个课程日：服装店', 6, 'published', timezone('utc', now()), '{"title":"询问是否有","pattern":"Do you have + 物品?","explanation":"在商店询问库存、颜色或尺码，都可以用 Do you have。","exampleEnglish":"Do you have this in blue?","exampleChinese":"这件有蓝色吗？"}'::jsonb, '[{"speaker":"Lin","english":"Do you have this in a small?","chinese":"这件有小码吗？"},{"speaker":"Staff","english":"Yes. Would you like blue or black?","chinese":"有，你想要蓝色还是黑色？"},{"speaker":"Lin","english":"Blue, please. Can I try it on?","chinese":"蓝色。我可以试穿吗？"},{"speaker":"Staff","english":"Sure. The fitting room is there.","chinese":"可以，试衣间在那里。"}]'::jsonb, '不只看标签', 'Lin likes a blue jacket, but the first one is too large. She asks for a small size and tries it on. The sleeves fit well, and the color looks good in daylight. She walks around for a minute before deciding.', '小林喜欢一件蓝色夹克，但第一件太大。她询问小码并试穿。袖子很合适，颜色在自然光下也很好看。决定购买前，她穿着走了一分钟。', 1)
