insert into public.lessons (slug, course_order, unit_order, unit_title, title, scene_title, summary, duration_minutes, status, published_at, grammar, dialogue, story_title, story_english, story_chinese, content_version)
values ('survival-30', 30, 6, '独立旅行', '我真的可以出发', '独自在国外的一天', '第 30 个课程日：独自在国外的一天', 6, 'published', timezone('utc', now()), '{"title":"表达能力","pattern":"I can + 动词原形","explanation":"can 后接动词原形，告诉自己会做、能做。","exampleEnglish":"I can ask for help.","exampleChinese":"我可以开口求助。"}'::jsonb, '[{"speaker":"Anna","english":"Were you nervous on your first day?","chinese":"第一天你紧张吗？"},{"speaker":"Lin","english":"Yes, but I spoke anyway.","chinese":"紧张，但我还是开口了。"},{"speaker":"Anna","english":"You traveled alone and solved many problems.","chinese":"你独自旅行，还解决了很多问题。"},{"speaker":"Lin","english":"I can do this. This is only the beginning.","chinese":"我可以做到，这只是开始。"}]'::jsonb, '独自在国外的一天', 'Lin starts the day by ordering breakfast in English. She takes the subway, asks for directions, visits a museum, and buys a small gift. When it rains, she changes her plan. When she does not understand, she asks people to repeat. She is not fearless or perfect. She is simply ready to try, brave enough to speak, and able to continue her journey.', '小林用英语点早餐开始新的一天。她乘地铁、问路、参观博物馆并买了一份小礼物。下雨时她调整计划，听不懂时请别人重复。她并非毫无畏惧，也不完美，只是愿意尝试、敢于开口，并能够继续自己的旅程。', 1)
on conflict (slug) do update set
  course_order = excluded.course_order, unit_order = excluded.unit_order, unit_title = excluded.unit_title,
  title = excluded.title, scene_title = excluded.scene_title, summary = excluded.summary, duration_minutes = excluded.duration_minutes,
  status = excluded.status, published_at = excluded.published_at, grammar = excluded.grammar, dialogue = excluded.dialogue,
  story_title = excluded.story_title, story_english = excluded.story_english, story_chinese = excluded.story_chinese,
  content_version = excluded.content_version, updated_at = timezone('utc', now());

